Shared rules for sweep fix workers (caliper repo):
- Your trail body (entire trail show <n>) lists branches. Do each branch SEQUENTIALLY: create it from origin/main (unless the body names a different base), reproduce the problem FIRST with a failing test or command (exact-content assertions, never bare is_ok/is_err), fix minimally, make the test pass, run the targeted tests plus the crate's full tests (cargo nextest/just recipes; see justfile), commit signed, push, then `entire trail link <n> --branch <b> --base <base>`.
- Smallest fix only. No refactors beyond the finding, no new abstractions unless the finding is about duplication. If a finding does not reproduce on current origin/main, do not fix it: report it as not reproduced with the evidence.
- Sandbox off for git commit/push and gh/entire (one plain git command per call). Never open PRs, never merge, never force-push, never touch main. Do not edit .github/workflows/callisto-release.yml or callisto.toml.
- No markdown tables in anything. Write comments in present tense, why not history; no SPEC/AC/trail tags.
- Source of findings: /tmp/claude-501/sweep/PHASE6.md (read the relevant items) and sweep JSON in that dir (p1-all.json, p2-*.json, p3-*.json, p5-*.json) for file/line detail; line numbers may be off by some lines.
- Final report: per branch: name, commit sha, what the test proved, anything not reproduced or not done, anything not run. Keep it short.
// The native binding inside `node:worker_threads`, where Storybook 11 runs docgen providers: each worker loads the
// addon, extracts, and runs its own watch session, several at once and again after earlier workers have exited.

import { describe, it, expect } from 'vitest'
import { Worker } from 'node:worker_threads'
import * as path from 'node:path'
import { fileURLToPath } from 'node:url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const PROBE = path.join(__dirname, 'fixtures/worker-probe.mjs')
const SRC = path.join(__dirname, 'fixtures/src')

let napiAvailable = false
try {
  await import('caliper-docgen-napi')
  napiAvailable = true
} catch {
  napiAvailable = false
}
if (!napiAvailable && process.env.NAPI_BINARY_REQUIRED === 'true') {
  throw new Error('caliper-docgen-napi did not load; build it with `pnpm --filter caliper-docgen-napi build:napi`')
}

interface ProbeResult {
  cold: string[]
  session: string[]
  sessionId: number
}

function runProbe(): Promise<ProbeResult> {
  return new Promise((resolve, reject) => {
    const worker = new Worker(PROBE, { workerData: { srcDir: SRC } })
    worker.once('message', resolve)
    worker.once('error', reject)
    worker.once('exit', (code) => {
      if (code !== 0) reject(new Error(`worker exited with ${code}`))
    })
  })
}

describe.skipIf(!napiAvailable)('caliper-docgen-napi in worker threads', () => {
  it('extracts and runs a session in several workers at once, and again after they exit', async () => {
    const concurrent = await Promise.all([runProbe(), runProbe(), runProbe()])
    for (const result of concurrent) {
      expect(result.cold).toEqual(['Button'])
      expect(result.session).toEqual(['Button'])
    }
    expect(new Set(concurrent.map((r) => r.sessionId)).size).toBe(3)

    const later = await runProbe()
    expect(later.cold).toEqual(['Button'])
    expect(later.session).toEqual(['Button'])
  })
})
