pub(super) fn discover_dirs(
    src_dirs: &[Utf8PathBuf],
    extra_excludes: &[String],
    is_config: impl Fn(&str) -> bool,
) -> (Vec<Utf8PathBuf>, Vec<Utf8PathBuf>) {
