        // --src, absolute --src, cwd inside the src dir). A dangling symlink keeps its own path rather than being
        // dropped.
        Ok(utf8) if entry.path_is_symlink() => Some(Ok(utf8.canonicalize_utf8().unwrap_or(utf8))),

